const j = $input.first().json;
const isWebhook = !!(j && (j.webhookUrl || j.headers));
const body = (j && j.body) || {};
return [{ json: {
  run_id: 'wf2-' + $execution.id,
  started_at: new Date().toISOString(),
  trigger: isWebhook ? 'webhook' : 'schedule',
  note: body.note || ''
}}];

const parseMaybe = v => { if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch(e){ return v; } };
const brandRows = $('Read Brand').all().map(i=>i.json).filter(r=>r.brand_name);
if (!brandRows.length) throw new Error('No brand constitution found. Run WF1 first.');
const brandRaw = brandRows[brandRows.length-1];
const brand = {};
for (const [k,v] of Object.entries(brandRaw)) { if (k !== 'one_pager_md' && k !== 'row_number') brand[k] = parseMaybe(v); }
const cfgRows = $('Read Config').all().map(i=>i.json).filter(r=>r.key);
const config = Object.fromEntries(cfgRows.map(r=>[r.key, String(r.value)]));
const batch = parseInt(config.batch_counter || '1', 10);
const learnRows = $('Read Learnings').all().map(i=>i.json).filter(r=>r.directive);
const learnings = learnRows.filter(r=>String(r.applied_in_batch)===String(batch)).map(l=>({type:l.insight_type, dimension:l.dimension, directive:l.directive, evidence:l.evidence}));
const calRows = $('Read Calendar').all().map(i=>i.json).filter(r=>r.post_id);
const pastTopics = calRows.map(r=>r.topic).filter(Boolean);
const postsPerBatch = parseInt(config.posts_per_batch || '7', 10);
const cadence = (typeof brand.posting_cadence === 'object' && brand.posting_cadence) ? brand.posting_cadence : {slots:[{time:'20:00',label:'evening'}], formats:{reel:1,carousel:1,image:5}};
const start = DateTime.now().setZone('Africa/Cairo').plus({days:1});
const days = [];
for (let d=0; d<postsPerBatch; d++) days.push(start.plus({days:d}).toFormat('yyyy-MM-dd'));
let cost_before = null;
try { const c = $('Cost Before').first().json; cost_before = c.data ? c.data.usage : null; } catch(e) {}
return [{json: {
  run_id: $('Init Run').first().json.run_id,
  started_at: $('Init Run').first().json.started_at,
  batch_id: batch,
  posts_per_batch: postsPerBatch,
  brand, config, learnings,
  past_topics: pastTopics,
  days,
  slots: cadence.slots || [],
  formats: cadence.formats || {reel:1,carousel:1,image:5},
  cost_before
}}];

