const posts = $('Creative Director').first().json.output.posts;
const evals = $input.first().json.output.evaluations;
const brand = $('Build Creative Brief').first().json.brand;
const always = Array.isArray(brand.hashtags_always) ? brand.hashtags_always : [];
const banned = (Array.isArray(brand.hashtags_banned) ? brand.hashtags_banned : []).map(t=>String(t).toLowerCase());
const evalMap = Object.fromEntries(evals.map(e=>[e.post_id, e]));
const out = posts.map(p=>{
  const e = evalMap[p.post_id] || {};
  const tags = (p.hashtags||[]).map(String);
  const lintIssues = [];
  if (!(tags.length>=7 && tags.length<=11)) lintIssues.push('hashtag count '+tags.length);
  for (const a of always) if (!tags.map(t=>t.toLowerCase()).includes(String(a).toLowerCase())) lintIssues.push('missing always tag '+a);
  for (const t of tags) if (banned.includes(t.toLowerCase())) lintIssues.push('banned tag '+t);
  if (!p.caption_ar || p.caption_ar.length<20) lintIssues.push('caption_ar too short');
  if (!p.caption_en || p.caption_en.length<20) lintIssues.push('caption_en too short');
  if ((p.caption_en||'').length>2200) lintIssues.push('caption_en too long');
  if ((p.caption_ar||'').length>2200) lintIssues.push('caption_ar too long');
  if (p.format==='reel' && (!p.reel_storyboard || !p.reel_storyboard.length)) lintIssues.push('reel missing storyboard');
  const lint_pass = lintIssues.length===0;
  const judged_pass = e.pass===true;
  return {...p,
    judge_brand_score: e.brand_consistency ?? '',
    judge_arabic_score: e.arabic_naturalness ?? '',
    judge_platform_score: e.platform_fit ?? '',
    judge_notes: e.revision_notes || '',
    lint_issues: lintIssues.join('; '),
    lint_pass,
    revision_count: 0,
    needs_revision: !(judged_pass && lint_pass)
  };
});
const reels = out.filter(p=>p.format==='reel').length;
const batchIssues = [];
if (reels!==1) batchIssues.push('expected exactly 1 reel, got '+reels);
return [{json:{
  posts: out,
  any_revision: out.some(p=>p.needs_revision) || batchIssues.length>0,
  batch_issues: batchIssues.join('; '),
  pre_scores: out.map(p=>({post_id:p.post_id, brand:p.judge_brand_score, arabic:p.judge_arabic_score, platform:p.judge_platform_score}))
}}];

let base;
try { base = $('Merge Final Batch').first().json; } catch(e) { base = null; }
if (!base || !base.posts) base = $('Apply Verdicts And Lint').first().json;
let human_feedback = '';
try { human_feedback = String(($('Approval Gate').first().json || {})['Feedback'] || ''); } catch(e) {}
return [{json:{
  posts: base.posts,
  batch_issues: base.batch_issues || '',
  human_feedback,
  brand: $('Build Creative Brief').first().json.brand,
  batch_id: $('Build Creative Brief').first().json.batch_id
}}];

