const revised = $('Reviser').first().json.output.posts;
const base = $('Prep Revision').first().json.posts;
const revMap = Object.fromEntries(revised.map(p=>[p.post_id,p]));
const posts = base.map(p => revMap[p.post_id] ? revMap[p.post_id] : p);
const evals = $input.first().json.output.evaluations;
const evalMap = Object.fromEntries(evals.map(e=>[e.post_id,e]));
const pre = Object.fromEntries((($('Apply Verdicts And Lint').first().json.pre_scores)||[]).map(s=>[s.post_id,s]));
const brand = $('Build Creative Brief').first().json.brand;
const always = Array.isArray(brand.hashtags_always) ? brand.hashtags_always : [];
const banned = (Array.isArray(brand.hashtags_banned) ? brand.hashtags_banned : []).map(t=>String(t).toLowerCase());
const out = posts.map(p=>{
  const e = evalMap[p.post_id]||{};
  const tags=(p.hashtags||[]).map(String);
  const issues=[];
  if(!(tags.length>=7&&tags.length<=11)) issues.push('hashtag count '+tags.length);
  for(const a of always) if(!tags.map(t=>t.toLowerCase()).includes(String(a).toLowerCase())) issues.push('missing always tag '+a);
  for(const t of tags) if(banned.includes(t.toLowerCase())) issues.push('banned tag '+t);
  return {...p,
    judge_brand_score: e.brand_consistency ?? p.judge_brand_score,
    judge_arabic_score: e.arabic_naturalness ?? p.judge_arabic_score,
    judge_platform_score: e.platform_fit ?? p.judge_platform_score,
    judge_notes: e.revision_notes || '',
    judge_brand_score_pre: (pre[p.post_id]||{}).brand ?? '',
    judge_arabic_score_pre: (pre[p.post_id]||{}).arabic ?? '',
    lint_issues: issues.join('; '),
    lint_pass: issues.length===0,
    revision_count: (parseInt(p.revision_count,10)||0)+1
  };
});
return [{json:{posts: out, revised: true}}];

const inp = $input.first().json;
const posts = inp.posts;
const briefJ = $('Build Creative Brief').first().json;
const batch = briefJ.batch_id;
function fnv(str){let h=0x811c9dc5;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,0x01000193)>>>0;}return h;}
const rows = posts.map(p=>{
  const seed = fnv(String(p.post_id)) % 100000;
  const promptTxt = encodeURIComponent(String(p.image_prompt||'').slice(0,300));
  const image_url = 'https://image.pollinations.ai/prompt/' + promptTxt + '?width=1080&height=1350&seed=' + seed + '&nologo=true';
  const publish_at = DateTime.fromISO(p.date + 'T' + (p.slot_time||'20:00') + ':00', {zone:'Africa/Cairo'}).toISO();
  return { json: {
    post_id: p.post_id, batch_id: String(batch),
    publish_at, slot_label: p.slot_label||'', format: p.format, pillar: p.pillar, topic: p.topic,
    caption_en: p.caption_en, caption_ar: p.caption_ar,
    hashtags: (p.hashtags||[]).join(' '),
    image_prompt: p.image_prompt||'', image_url,
    reel_hook: p.reel_hook||'', reel_storyboard: p.reel_storyboard?JSON.stringify(p.reel_storyboard):'',
    reel_audio: p.reel_audio||'', reel_cover_text: p.reel_cover_text||'',
    cta: p.cta||'', rationale: p.rationale||'',
    status: 'pending',
    judge_brand_score: String(p.judge_brand_score??''), judge_arabic_score: String(p.judge_arabic_score??''), judge_platform_score: String(p.judge_platform_score??''),
    judge_notes: p.judge_notes||'',
    judge_brand_score_pre: String((p.judge_brand_score_pre??p.judge_brand_score)??''),
    judge_arabic_score_pre: String((p.judge_arabic_score_pre??p.judge_arabic_score)??''),
    lint_pass: String(p.lint_pass!==false), revision_count: String(p.revision_count||0),
    approved_at:'', published_at:'', media_id:'', api_payload_log:'',
    created_at: new Date().toISOString()
  }};
});
return rows;

const rows = $input.all().map(i=>i.json);
const batch = rows.length ? rows[0].batch_id : '?';
const esc = s => String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;');
const approval_url = $execution.resumeFormUrl;
let html = '<h2>InstaBay content batch ' + batch + ' - approval needed</h2>';
html += '<p><a href="' + approval_url + '"><b>Open the approval form</b></a> to approve all or request changes.</p>';
html += '<p>' + rows.length + ' posts:</p>';
for (const r of rows){
  html += '<hr><h3>' + esc(r.post_id) + ' | ' + esc(r.format) + ' | ' + esc(r.pillar) + ' | ' + esc(r.publish_at) + '</h3>'
  + '<p><b>Topic:</b> ' + esc(r.topic) + '</p>'
  + '<p><b>EN:</b> ' + esc(r.caption_en).replace(/\n/g,'<br>') + '</p>'
  + '<p dir="rtl" style="text-align:right"><b>AR:</b> ' + esc(r.caption_ar).replace(/\n/g,'<br>') + '</p>'
  + '<p><b>Hashtags:</b> ' + esc(r.hashtags) + '</p>'
  + '<p><b>Judge:</b> brand ' + r.judge_brand_score + '/5, arabic ' + r.judge_arabic_score + '/5, platform ' + r.judge_platform_score + '/5 | lint ' + r.lint_pass + '</p>'
  + (r.format==='reel' ? '<p><b>Reel hook:</b> ' + esc(r.reel_hook) + '<br><b>Storyboard:</b> ' + esc(r.reel_storyboard) + '</p>' : '')
  + '<p><a href="' + r.image_url + '">visual preview</a></p>';
}
html += '<hr><p>Sheet: https://docs.google.com/spreadsheets/d/YOUR_GOOGLE_SHEET_ID/edit</p>';
return [{json:{subject: 'InstaBay batch ' + batch + ': approve ' + rows.length + ' posts', html, batch_id: batch, posts_count: rows.length, approval_url}}];

const rows = $('Upsert Calendar').all().map(i=>i.json);
const now = new Date().toISOString();
return rows.map(r=>({json:{post_id: r.post_id, status:'approved', approved_at: now}}));

const brief = $('Build Creative Brief').first().json;
const started = brief.started_at;
const finished = new Date().toISOString();
const duration_s = Math.round((new Date(finished).getTime()-new Date(started).getTime())/1000);
let cost = '';
try {
  const before = brief.cost_before;
  const afterJ = $('Cost After').first().json;
  const after = afterJ.data ? afterJ.data.usage : null;
  if (before!=null && after!=null) cost = String(Math.round((after-before)*10000)/10000);
} catch(e){}
const posts_count = $('Mark Approved').all().length;
const cpp = (cost && posts_count) ? String(Math.round(parseFloat(cost)/posts_count*10000)/10000) : '';
return [{json:{
  run_id: brief.run_id, workflow:'WF2-content-studio', batch_id: String(brief.batch_id),
  started_at: started, finished_at: finished, duration_s: String(duration_s),
  llm_cost_usd: cost, posts_count: String(posts_count),
  cost_per_post_usd: cpp,
  notes: 'batch generated, judged, approved'
}}];

const cfg = $('Read Config').all().map(i=>i.json);
const row = cfg.find(r=>r.key==='batch_counter');
if (!row) throw new Error('batch_counter row not found in Config');
const next = String(parseInt(row.value,10)+1);
return [{json:{row_number: row.row_number, key:'batch_counter', value: next}}];

const out = $input.first().json.output;
if (!out || !Array.isArray(out.posts)) throw new Error('Creative output missing posts array - likely truncated or malformed generation');
const brief = $('Build Creative Brief').first().json;
if (out.posts.length !== brief.posts_per_batch) throw new Error('Creative output has ' + out.posts.length + ' posts, expected ' + brief.posts_per_batch + ' - likely truncated generation or autofix hallucination');
const re = new RegExp('^b' + brief.batch_id + '-p\\d+$');
const bad = out.posts.filter(p => !re.test(String(p.post_id)));
if (bad.length) throw new Error('post_id pattern violation: ' + bad.map(p=>p.post_id).join(', '));
return [{json: {output: out}}];

const j = $input.first().json;
const brief = $('Build Creative Brief').first().json;
return [{json:{
  run_id: brief.run_id, workflow: 'WF2-approval-link', batch_id: String(brief.batch_id),
  started_at: brief.started_at, finished_at: '', duration_s: '',
  llm_cost_usd: '', posts_count: String(j.posts_count), cost_per_post_usd: '',
  notes: j.approval_url
}}];
